script:
(function () {
  'use strict';
  // Payback period: the time for cumulative cash flow (starting at -initial investment) to reach 0.
  //   If the running total turns non-negative in year t, payback = (t - 1) + (shortfall at the start
  //   of year t) / (cash flow in year t), assuming cash arrives evenly through the year.
  // Discounted payback does the same with each year's flow divided by (1 + d)^t.
  // NPV = -initial + sum CF_t / (1 + d)^t; profitability index = PV of inflows / initial.
  // Fixed mode: CF_t = CF_1 * (1 + g)^(t - 1).
  // Verified (Node): $100,000 with $25,000 a year -> 4.00 years; [-10000, 2000, 3000, 4000, 4000,
  // 3000] -> 3.25 years (same as the site's IRR calculator); $100,000 with $30,000 a year at 10% ->
  // discounted payback 4.2633 years, 5-year NPV $13,723.60 (annuity factor 3.790787); cash flows that
  // never recover -> "Not reached".
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var MAX_YEARS = 100, MAX_ROWS = 50;

  // --- calc start
  function paybackPeriod(initial, flows) {
    var cum = -initial;
    if (cum >= 0) return 0;
    for (var t = 0; t < flows.length; t++) {
      var next = cum + flows[t];
      if (next >= 0 && flows[t] > 0) return t + (-cum) / flows[t];
      cum = next;
    }
    return null;
  }

  function discounted(flows, d) {
    return flows.map(function (cf, t) { return cf / Math.pow(1 + d, t + 1); });
  }

  function fixedFlows(first, growth, years) {
    var out = [];
    for (var t = 0; t < years; t++) out.push(first * Math.pow(1 + growth, t));
    return out;
  }
  // --- calc end

  function el(id) { return document.getElementById(id); }
  function rowInputs() { return Array.prototype.slice.call(document.querySelectorAll('#pbRows input')); }
  function years(x) {
    if (x === null) return 'Not reached';
    return x.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' years';
  }

  function syncButtons() {
    var count = rowInputs().length;
    el('pbAdd').disabled = count >= MAX_ROWS;
    el('pbRemove').disabled = count <= 1;
  }

  function addRow() {
    var n = rowInputs().length + 1;
    if (n > MAX_ROWS) return;
    var wrap = document.createElement('div');
    wrap.className = 'flex items-center gap-3';
    var label = document.createElement('label');
    label.className = 'w-24 shrink-0 text-sm text-ink-muted';
    label.htmlFor = 'pbCf' + n;
    label.textContent = 'Year ' + n;
    var group = document.createElement('div');
    group.className = 'input-group flex-1';
    var affix = document.createElement('span');
    affix.className = 'input-affix';
    affix.textContent = '$';
    var input = document.createElement('input');
    input.type = 'number';
    input.id = 'pbCf' + n;
    input.className = 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none';
    input.step = '1000';
    input.value = '0';
    input.setAttribute('inputmode', 'decimal');
    group.appendChild(affix);
    group.appendChild(input);
    wrap.appendChild(label);
    wrap.appendChild(group);
    el('pbRows').appendChild(wrap);
    syncButtons();
    update();
    input.focus();
  }

  function removeRow() {
    var rows = el('pbRows');
    if (rowInputs().length <= 1) return;
    rows.removeChild(rows.lastElementChild);
    syncButtons();
    update();
  }

  function clear() {
    ['pbPayback', 'pbDiscounted', 'pbNpv', 'pbNet', 'pbInflows', 'pbPv', 'pbIndex'].forEach(function (id) {
      el(id).textContent = '–';
    });
    el('pbSchedule').innerHTML = '';
    el('pbNote').hidden = true;
  }

  function update() {
    var fixed = el('pbMode').value === 'fixed';
    el('pbFixedWrap').hidden = !fixed;
    el('pbVariedWrap').hidden = fixed;
    var initial = parseFloat(el('pbInitial').value), d = parseFloat(el('pbDiscount').value);
    var msg = '', flows = [];
    if (isNaN(initial) || initial <= 0 || initial > 1e12) msg = 'Enter an initial investment above $0 and up to $1 trillion.';
    else if (isNaN(d) || d < 0 || d > 100) msg = 'Enter a discount rate from 0% to 100%.';
    else if (fixed) {
      var first = parseFloat(el('pbFlow').value), g = parseFloat(el('pbGrowth').value), n = parseFloat(el('pbYears').value);
      if (isNaN(first) || Math.abs(first) > 1e12) msg = 'Enter the year 1 cash flow (up to $1 trillion).';
      else if (isNaN(g) || g < -50 || g > 100) msg = 'Enter a yearly change from -50% to 100%.';
      else if (isNaN(n) || n < 1 || n > MAX_YEARS || Math.round(n) !== n) msg = 'Enter 1 to 100 whole years.';
      else flows = fixedFlows(first, g / 100, n);
    } else {
      rowInputs().forEach(function (input) {
        var v = input.value.trim() === '' ? 0 : parseFloat(input.value);
        if (!isFinite(v) || Math.abs(v) > 1e12) msg = 'Each cash flow must be a number up to $1 trillion.';
        flows.push(v);
      });
    }
    if (!msg && flows.some(function (v) { return !isFinite(v) || Math.abs(v) > 1e15; })) msg = 'These cash flows grow too large to show. Lower the yearly change or the number of years.';
    var error = el('pbError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clear(); return; }

    var rate = d / 100, pv = discounted(flows, rate);
    var pb = paybackPeriod(initial, flows), dpb = paybackPeriod(initial, pv);
    var inflows = 0, pvIn = 0, sum = 0, pvSum = 0;
    flows.forEach(function (cf, t) {
      sum += cf; pvSum += pv[t];
      if (cf > 0) { inflows += cf; pvIn += pv[t]; }
    });
    el('pbPayback').textContent = years(pb);
    el('pbDiscounted').textContent = years(dpb);
    el('pbNpv').textContent = money.format(pvSum - initial);
    el('pbNet').textContent = money.format(sum - initial);
    el('pbInflows').textContent = money.format(inflows);
    el('pbPv').textContent = money.format(pvIn);
    el('pbIndex').textContent = (pvSum / initial).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    var note = el('pbNote');
    note.hidden = true;
    if (pb === null) {
      note.textContent = 'The cash flows entered never add up to the initial investment, so it does not pay back within ' + flows.length + (flows.length === 1 ? ' year.' : ' years.');
      note.hidden = false;
    } else if (dpb === null) {
      note.textContent = 'The investment pays back in cash terms, but not once each year\'s cash is discounted at ' + d + '%. At that rate it does not earn back its cost within ' + flows.length + (flows.length === 1 ? ' year.' : ' years.');
      note.hidden = false;
    }

    var cum = -initial, cumPv = -initial;
    var rows = ['<tr><td>0</td><td>' + money.format(-initial) + '</td><td>' + money.format(cum) + '</td><td>' +
                money.format(-initial) + '</td><td>' + money.format(cumPv) + '</td></tr>'];
    flows.forEach(function (cf, t) {
      cum += cf; cumPv += pv[t];
      rows.push('<tr><td>' + (t + 1) + '</td><td>' + money.format(cf) + '</td><td>' + money.format(cum) + '</td><td>' +
                money.format(pv[t]) + '</td><td>' + money.format(cumPv) + '</td></tr>');
    });
    el('pbSchedule').innerHTML = rows.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('pbForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('pbAdd').addEventListener('click', addRow);
    el('pbRemove').addEventListener('click', removeRow);
    syncButtons();
    update();
  });
})();
